/* ================= Geometry helpers ================= */
function mergeGeoms(list) {
  let total = 0;
  const prepped = list.map(g => {
    const ng = g.index ? g.toNonIndexed() : g;
    total += ng.attributes.position.count;
    return ng;
  });
  const pos = new Float32Array(total * 3), nor = new Float32Array(total * 3),
    uv = new Float32Array(total * 2), col = new Float32Array(total * 3);
  let o = 0;
  for (const g of prepped) {
    const n = g.attributes.position.count;
    pos.set(g.attributes.position.array, o * 3);
    if (g.attributes.normal) nor.set(g.attributes.normal.array, o * 3);
    if (g.attributes.uv) uv.set(g.attributes.uv.array, o * 2);
    if (g.attributes.color) col.set(g.attributes.color.array, o * 3);
    else col.fill(1, o * 3, (o + n) * 3);
    o += n;
  }
  const out = new THREE.BufferGeometry();
  out.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  out.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  out.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  out.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return out;
}
function bakeTransform(geo, pos, quat, scale) {
  const m = new THREE.Matrix4().compose(
    pos || new THREE.Vector3(),
    quat || new THREE.Quaternion(),
    scale || new THREE.Vector3(1, 1, 1));
  geo.applyMatrix4(m);
  return geo;
}
function flatRibbon(s0, s1, step, dA, dB, yOff, colorFn, uvS, uvD) {
  const rows = [];
  for (let s = s0; s <= s1 + 1e-6; s += step) rows.push(Math.min(s, s1));
  const nR = rows.length;
  const pos = new Float32Array(nR * 2 * 3), nor = new Float32Array(nR * 2 * 3),
    uv = new Float32Array(nR * 2 * 2), col = new Float32Array(nR * 2 * 3);
  const idx = [];
  for (let i = 0; i < nR; i++) {
    const f = frameAt(rows[i]);
    for (let j = 0; j < 2; j++) {
      const d = j === 0 ? dA : dB;
      const vi = (i * 2 + j);
      pos[vi * 3] = f.p.x + f.n.x * d;
      pos[vi * 3 + 1] = f.p.y + yOff;
      pos[vi * 3 + 2] = f.p.z + f.n.z * d;
      nor[vi * 3] = 0; nor[vi * 3 + 1] = 1; nor[vi * 3 + 2] = 0;
      uv[vi * 2] = (rows[i] - s0) / uvS;
      uv[vi * 2 + 1] = (d - dA) / uvD;
      const c = colorFn ? colorFn(rows[i], d) : [1, 1, 1];
      col[vi * 3] = c[0]; col[vi * 3 + 1] = c[1]; col[vi * 3 + 2] = c[2];
    }
    if (i < nR - 1) {
      const a = i * 2;
      idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  g.setIndex(idx);
  return g;
}
function wallRibbon(s0, s1, step, d, y0, y1, uvS, uvD, flip) {
  const rows = [];
  for (let s = s0; s <= s1 + 1e-6; s += step) rows.push(Math.min(s, s1));
  const nR = rows.length;
  const pos = new Float32Array(nR * 2 * 3), nor = new Float32Array(nR * 2 * 3), uv = new Float32Array(nR * 2 * 2);
  const idx = [];
  for (let i = 0; i < nR; i++) {
    const f = frameAt(rows[i]);
    for (let j = 0; j < 2; j++) {
      const vi = i * 2 + j;
      pos[vi * 3] = f.p.x + f.n.x * d;
      pos[vi * 3 + 1] = f.p.y + (j === 0 ? y0 : y1);
      pos[vi * 3 + 2] = f.p.z + f.n.z * d;
      const sgn = flip ? -1 : 1;
      nor[vi * 3] = f.n.x * sgn; nor[vi * 3 + 1] = 0; nor[vi * 3 + 2] = f.n.z * sgn;
      uv[vi * 2] = (rows[i] - s0) / uvS;
      uv[vi * 2 + 1] = j;
    }
    if (i < nR - 1) {
      const a = i * 2;
      if (flip) idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      else idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.BufferAttribute(nor, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setIndex(idx);
  return g;
}
function trackQuad(sC, dC, len, wid, yOff) {
  const f = frameAt(sC);
  const pos = new Float32Array(12), uv = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);
  const corners = [[-len / 2, -wid / 2], [len / 2, -wid / 2], [-len / 2, wid / 2], [len / 2, wid / 2]];
  for (let i = 0; i < 4; i++) {
    const [ds, dd] = corners[i];
    pos[i * 3] = f.p.x + f.t.x * ds + f.n.x * (dC + dd);
    pos[i * 3 + 1] = f.p.y + yOff;
    pos[i * 3 + 2] = f.p.z + f.t.z * ds + f.n.z * (dC + dd);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  g.setIndex([0, 2, 1, 1, 2, 3]);
  g.computeVertexNormals();
  return g;
}

/* ================= Floodlight mast layout & baked pools ================= */
const MASTS = [];
{
  const count = Math.round(L / 70);
  for (let i = 0; i < count; i++) {
    const s = 30 + i * (L / count);
    const side = i % 2 === 0 ? 1 : -1;
    const f = frameAt(s);
    const base = f.p.clone().addScaledVector(f.n, side * 11.5);
    const lamp = base.clone(); lamp.y += 29;
    const target = f.p.clone().addScaledVector(f.n, side * 1.5);
    MASTS.push({ s, side, base, lamp, target });
  }
}
function wrapDelta(a, b) {
  let d = Math.abs(modL(a) - modL(b));
  return Math.min(d, L - d);
}
function poolAt(s, d) {
  let p = 0;
  for (const m of MASTS) {
    const da = wrapDelta(s, m.s);
    if (da > 45) continue;
    const dd = d - m.side * 2.5;
    p += Math.exp(-(da * da) / (17 * 17) - (dd * dd) / (8.5 * 8.5)) * 1.15;
  }
  const ws = modL(s);
  if (ws < 225 || ws > L - 45) p += 0.30 * Math.exp(-((d - 5.5) * (d - 5.5)) / 40);
  return p;
}
const roadColor = (s, d) => {
  const c = 0.30 + poolAt(s, d) * 1.55;
  return [c * 0.92, c * 0.97, c * 1.10];
};

/* ================= Road, lines, kerbs ================= */
{
  const road = new THREE.Mesh(flatRibbon(0, L, L / 900, -7, 7, 0, roadColor, 4, 4), MAT.asphalt);
  road.receiveShadow = true;
  scene.add(road);
  const lineL = new THREE.Mesh(flatRibbon(0, L, L / 600, -6.95, -6.65, 0.015, null, 4, 1), MAT.whiteLine);
  const lineR = new THREE.Mesh(flatRibbon(0, L, L / 600, 6.65, 6.95, 0.015, null, 4, 1), MAT.whiteLine);
  scene.add(lineL, lineR);
  const kerbGeos = [];
  for (let s = 0; s < L; s += 3) {
    const k = curvAt(s + 1.5);
    if (Math.abs(k) < 0.0055) continue;
    const red = Math.floor(s / 3) % 2 === 0;
    const c = red ? [0.62, 0.05, 0.09] : [0.78, 0.78, 0.78];
    for (const side of [-1, 1]) {
      const dA = side === 1 ? 7.0 : -8.2, dB = side === 1 ? 8.2 : -7.0;
      kerbGeos.push(flatRibbon(s, s + 3, 1.5, dA, dB, 0.03, () => c, 3, 1.2));
    }
  }
  const kerbs = new THREE.Mesh(mergeGeoms(kerbGeos), MAT.kerb);
  kerbs.receiveShadow = true;
  scene.add(kerbs);
  const finish = new THREE.Mesh(trackQuad(0, 0, 1.6, 14, 0.025),
    new THREE.MeshBasicMaterial({ map: checkerTex }));
  scene.add(finish);
  const gridMat = new THREE.MeshBasicMaterial({ map: gridBoxTex, transparent: true, depthWrite: false });
  scene.add(new THREE.Mesh(trackQuad(-8, -2.5, 6.4, 2.7, 0.02), gridMat));
  scene.add(new THREE.Mesh(trackQuad(-16, 2.5, 6.4, 2.7, 0.02), gridMat));
}

/* ================= Barriers & catch fencing ================= */
{
  const wallGeos = [], fenceGeos = [], postGeos = [];
  for (const side of [-1, 1]) {
    const d = side * 9;
    wallGeos.push(wallRibbon(0, L, L / 700, d, 0, 1.05, 6, 1, side === 1));
    wallGeos.push(wallRibbon(0, L, L / 700, d - side * 0.12, 0.42, 0.62, 6, 1, side === 1));
    fenceGeos.push(wallRibbon(0, L, L / 700, d, 1.05, 3.1, 1.6, 2.05, side === 1));
    for (let s = 0; s < L; s += 12) {
      const f = frameAt(s);
      const p = f.p.clone().addScaledVector(f.n, d);
      const g = bakeTransform(new THREE.BoxGeometry(0.1, 3.2, 0.1),
        new THREE.Vector3(p.x, p.y + 1.6, p.z));
      postGeos.push(g);
    }
  }
  scene.add(new THREE.Mesh(mergeGeoms(wallGeos), MAT.barrier));
  const fenceMesh = new THREE.Mesh(mergeGeoms(fenceGeos), MAT.fence);
  scene.add(fenceMesh);
  scene.add(new THREE.Mesh(mergeGeoms(postGeos), MAT.pole));
}

/* ================= Floodlight masts, cones, glows, road sheen ================= */
const coneMat = new THREE.MeshBasicMaterial({
  color: 0x9fc2e8, transparent: true, opacity: 0.055, blending: THREE.AdditiveBlending,
  depthWrite: false, side: THREE.DoubleSide, vertexColors: true
});
{
  const poleGeos = [], headGeos = [], coneGeos = [];
  const glowMat = new THREE.SpriteMaterial({
    map: glowTex, color: 0xcfe0ff, transparent: true, opacity: 0.85,
    blending: THREE.AdditiveBlending, depthWrite: false
  });
  const sheenMat = new THREE.MeshBasicMaterial({
    map: ringTex, color: 0x8fb2dc, transparent: true, opacity: 0.10,
    blending: THREE.AdditiveBlending, depthWrite: false
  });
  for (const m of MASTS) {
    poleGeos.push(bakeTransform(new THREE.CylinderGeometry(0.16, 0.30, 29, 8),
      new THREE.Vector3(m.base.x, m.base.y + 14.5, m.base.z)));
    const dir = new THREE.Vector3().subVectors(m.target, m.lamp).normalize();
    const headQ = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), dir);
    headGeos.push(bakeTransform(new THREE.BoxGeometry(2.6, 1.3, 0.35), m.lamp, headQ));
    poleGeos.push(bakeTransform(new THREE.BoxGeometry(0.5, 0.5, 1.4),
      m.lamp.clone().addScaledVector(dir, -0.8), headQ));
    const coneH = 31, coneR = 9.5;
    const cone = new THREE.ConeGeometry(coneR, coneH, 14, 1, true);
    cone.translate(0, -coneH / 2, 0);
    const cnt = cone.attributes.position.count;
    const cc = new Float32Array(cnt * 3);
    for (let i = 0; i < cnt; i++) {
      const y = cone.attributes.position.getY(i);
      const v = clamp(1 + y / coneH, 0, 1);
      const b = 0.12 + v * v * 0.9;
      cc[i * 3] = b; cc[i * 3 + 1] = b; cc[i * 3 + 2] = b;
    }
    cone.setAttribute('color', new THREE.BufferAttribute(cc, 3));
    const coneQ = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, -1, 0), dir);
    coneGeos.push(bakeTransform(cone, m.lamp, coneQ));
    const spr = new THREE.Sprite(glowMat);
    spr.position.copy(m.lamp);
    spr.scale.set(9, 9, 1);
    scene.add(spr);
    const f = frameAt(m.s);
    const sheen = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), sheenMat);
    sheen.scale.set(34, 13, 1);
    sheen.position.copy(f.p).addScaledVector(f.n, m.side * 2);
    sheen.position.y += 0.04;
    sheen.rotation.x = -Math.PI / 2;
    sheen.rotation.z = -Math.atan2(f.t.z, f.t.x);
    scene.add(sheen);
  }
  scene.add(new THREE.Mesh(mergeGeoms(poleGeos), MAT.pole));
  scene.add(new THREE.Mesh(mergeGeoms(headGeos), MAT.lamp));
  scene.add(new THREE.Mesh(mergeGeoms(coneGeos), coneMat));
}

/* ================= Start gantry with five light pods ================= */
const podMats = [];
{
  const f = frameAt(2);
  const gantry = new THREE.Group();
  gantry.position.copy(f.p);
  gantry.rotation.y = Math.atan2(-f.t.z, f.t.x);
  const postGeo = new THREE.CylinderGeometry(0.14, 0.18, 7.2, 8);
  for (const side of [-1, 1]) {
    const post = new THREE.Mesh(postGeo, MAT.pole);
    post.position.set(0, 3.6, side * 8.4);
    gantry.add(post);
  }
  const beam = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.7, 17.4), MAT.pole);
  beam.position.set(0, 7.0, 0);
  gantry.add(beam);
  const panel = new THREE.Mesh(new THREE.BoxGeometry(0.25, 1.7, 11.4), MAT.darkPlastic);
  panel.position.set(0, 5.9, 0);
