/* ================= Terrain ================= */
{
  const W = 1500, H = 1300, SX = 96, SZ = 84;
  const geo = new THREE.PlaneGeometry(W, H, SX, SZ);
  geo.rotateX(-Math.PI / 2);
  const pos = geo.attributes.position;
  const col = new Float32Array(pos.count * 3);
  const coarse = [];
  for (let i = 0; i < NS; i += 10) coarse.push(SP[i]);
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i) + 50, z = pos.getZ(i) + 170;
    let best = 1e9, by = 0;
    for (const p of coarse) {
      const dx = x - p.x, dz = z - p.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < best) { best = d2; by = p.y; }
    }
    const dist = Math.sqrt(best);
    const hill = 8 + 20 * Math.sin(x * 0.006 + 1.7) * Math.cos(z * 0.005 + 0.4)
      + 11 * Math.sin(x * 0.017 + 3.1) * Math.sin(z * 0.013)
      + 5 * Math.sin(x * 0.041) * Math.cos(z * 0.037 + 1.2);
    const u = smoothstep(15, 110, dist);
    const y = lerp(by - 0.12, Math.max(hill, -1), u);
    pos.setXYZ(i, x, y, z);
    const g = 0.045 + 0.03 * Math.sin(x * 0.05) * Math.sin(z * 0.05);
    col[i * 3] = g * 0.85; col[i * 3 + 1] = g; col[i * 3 + 2] = g * 0.8;
  }
  geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
  geo.computeVertexNormals();
  const terrain = new THREE.Mesh(geo, MAT.terrain);
  scene.add(terrain);
}

/* ================= Traveling action lights ================= */
