keySpot.shadow.mapSize.set(1024, 1024);
keySpot.shadow.bias = -0.0004;
keySpot.shadow.camera.near = 4;
keySpot.shadow.camera.far = 120;
scene.add(keySpot, keySpot.target);
const rimSpot = new THREE.SpotLight(0xbfd4ff, 1.5, 190, 0.75, 0.65, 1.0);
scene.add(rimSpot, rimSpot.target);
