/* ================= Car construction ================= */
function loft(stations, radial) {
  radial = radial || 12;
  const nSt = stations.length;
  const pos = [], uv = [], idx = [];
  for (let i = 0; i < nSt; i++) {
    const st = stations[i];
    const yc = (st.y0 + st.y1) / 2, hh = Math.max(0.004, (st.y1 - st.y0) / 2);
    for (let k = 0; k < radial; k++) {
      const th = k / radial * TAU;
      const sz = Math.sin(th), cy = Math.cos(th);
      const z = st.w * Math.sign(sz) * Math.pow(Math.abs(sz), 0.72) + (st.zc || 0);
      const y = yc + hh * Math.sign(cy) * Math.pow(Math.abs(cy), 0.72);
      pos.push(st.x, y, z);
