}
function hideCountdown() {
  elCountdown.style.display = 'none';
  elCountdown.textContent = '';
}
function enterPlaying() {
  state = 'PLAYING';
  showPlayingIcons();
  AudioSys.setActive(true);
}
function enterPaused() {
  state = 'PAUSED';
  showPausedIcons();
  AudioSys.setActive(false);
}
elToggle.addEventListener('click', () => {
  if (state === 'PLAYING') {
    enterPaused();
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
    hideCountdown();
    simTime = 0;
    elScrubber.value = '0';
    renderAt(0);
    AudioSys.resetSim(0);
    enterPaused();
  } else if (state === 'PAUSED') {
    enterPlaying();
  } else if (state === 'ENDED') {
    simTime = 0;
    elScrubber.value = '0';
    hideCountdown();
    AudioSys.resetSim(0);
    renderAt(0);
    enterPlaying();
  }
});
elRefire.addEventListener('click', () => {
  hideCountdown();
  simTime = 0;
  countdownElapsed = 0;
  holdElapsed = 0;
  elScrubber.value = '0';
  renderAt(0);
  AudioSys.resetSim(0);
  AudioSys.setActive(false);
  showPlayingIcons();
