    state = 'COUNTDOWN';
    countdownElapsed = 0;
    elCountdown.style.display = 'block';
    elCountdown.textContent = '3';
    AudioSys.setActive(false);
    return;
  }
  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      enterPlaying();
    } else {
      elCountdown.style.display = 'block';
      elCountdown.textContent = countdownElapsed < 1 ? '3' : countdownElapsed < 2 ? '2' : '1';
      elScrubber.value = '0';
    }
    return;
  }
