input.content:
import Cocoa
import WebKit

let args = CommandLine.arguments
guard args.count >= 5 else { print("usage: webshot url out.png width height [waitSec]"); exit(1) }
let url = URL(string: args[1])!
let outPath = args[2]
let width = Double(args[3]) ?? 1920
let height = Double(args[4]) ?? 1080
let waitSec = args.count > 5 ? (Double(args[5]) ?? 6) : 6

class Delegate: NSObject, WKNavigationDelegate {
    var done = false
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) { done = true }
    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        print("NAVFAIL: \(error)"); done = true
    }
    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        print("NAVFAIL: \(error)"); done = true
    }
}

let app = NSApplication.shared
app.setActivationPolicy(.prohibited)
let config = WKWebViewConfiguration()
config.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
config.setValue(true, forKey: "allowUniversalAccessFromFileURLs")
config.mediaTypesRequiringUserActionForPlayback = []
let webView = WKWebView(frame: NSRect(x: 0, y: 0, width: width, height: height), configuration: config)
let delegate = Delegate()
webView.navigationDelegate = delegate
webView.load(URLRequest(url: url))
let deadline = Date().addingTimeInterval(waitSec)
while Date() < deadline {
    RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.05))
    if delegate.done && Date() > deadline.addingTimeInterval(-waitSec + 4.0) { }
}
// give late scripts a moment after load
let extra = Date().addingTimeInterval(delegate.done ? 1.0 : 2.0)
while Date() < extra { RunLoop.current.run(mode: .default, before: Date().addingTimeInterval(0.05)) }

webView.evaluateJavaScript("document.getElementById('__report') ? document.getElementById('__report').textContent : 'NO REPORT'") { result, err in
    if let r = result as? String { print("REPORT:\n\(r)") }
    if let e = err { print("JSERR: \(e)") }
    let cfg = WKSnapshotConfiguration()
    cfg.rect = webView.bounds
    webView.takeSnapshot(with: cfg) { image, error in
        if let image = image,
           let tiff = image.tiffRepresentation,
           let rep = NSBitmapImageRep(data: tiff),
           let png = rep.representation(using: .png, properties: [:]) {
            try? png.write(to: URL(fileURLWithPath: outPath))
            print("SAVED \(outPath)")
        } else {
            print("SNAPFAIL: \(String(describing: error))")
        }
        exit(0)
    }
}
RunLoop.current.run(until: Date().addingTimeInterval(30))
print("TIMEOUT")
exit(1)

