  function stats(){
    const c2 = document.createElement('canvas'); c2.width = cv.width; c2.height = cv.height;
    const g = c2.getContext('2d'); g.drawImage(cv, 0, 0);
    const W = c2.width, H = c2.height;
    const d = g.getImageData(0, Math.floor(H*0.55), W, Math.floor(H*0.35)).data;
    let sum=0,n=0,hi=0;
    for(let i=0;i<d.length;i+=4){ const l=0.2126*d[i]+0.7152*d[i+1]+0.0722*d[i+2]; sum+=l; n++; if(l>150)hi++; }
    return 'lowerMean=' + (sum/n).toFixed(1) + ' bright%=' + (100*hi/n).toFixed(1);
  }
  try {
    const t = parseFloat(q.get('t') || '0');
    renderAt(t);
    results.push('t=' + t + ' ' + stats() + ' R@' + proj(poseR.pos.clone().add(new THREE.Vector3(0,0.5,0))) + ' B@' + proj(poseB.pos.clone().add(new THREE.Vector3(0,0.5,0))));
