        renderAt(tt);
        AudioSys.frame(tt, 0.1, true);
      }
      AudioSys.frame(20, 0.1, true);
      AudioSys.setActive(false);
      AudioSys.frame(20, 0, false);
      results.push('audio sweep done, actx=' + (window.__actx ? window.__actx.state : 'none'));
    }
    if (q.get('sm') === '1') {
      const log = [];
      const cd = document.getElementById('countdown');
      const sc = document.getElementById('scrubber');
