      const rf = document.getElementById('btn-refire');
      // simulate rAF manually: capture callback
      results.push('initial state after load: cd.display=' + getComputedStyle(cd).display + ' text=' + cd.textContent);
      // INIT->COUNTDOWN happens on first rAF; our stub killed rAF, so drive loop via captured fn
      // loop was registered via requestAnimationFrame stub returning 0; we need the real callback.
      results.push('NOTE: rAF stubbed; state machine driven via events only');
