      log.push('scrub12.5: cd=' + getComputedStyle(cd).display + ' aria=' + tg.getAttribute('aria-label') + ' iconPlay=' + document.getElementById('icon-play').style.display);
      // toggle from PAUSED -> PLAYING
      tg.click();
      log.push('toggle: aria=' + tg.getAttribute('aria-label'));
      // toggle -> PAUSED
      tg.click();
      log.push('toggle2: aria=' + tg.getAttribute('aria-label'));
      // refire
      rf.click();
      log.push('refire: cd=' + getComputedStyle(cd).display + ' text=[' + cd.textContent + '] scrub=' + sc.value + ' aria=' + tg.getAttribute('aria-label'));
      // toggle during REFIRE_HOLD -> PAUSED at 0
      tg.click();
      log.push('toggle-hold: aria=' + tg.getAttribute('aria-label') + ' scrub=' + sc.value);
      // speed pill
      const p2 = document.querySelector('[data-speed=\"2.0\"]');
      p2.click();
      log.push('pill2: active=' + p2.classList.contains('is-active') + ' checked=' + p2.getAttribute('aria-checked') + ' p1checked=' + document.querySelector('[data-speed=\"1.0\"]').getAttribute('aria-checked'));
      results.push(log.join(String.fromCharCode(10)));
