window.requestAnimationFrame = function(){ return 0; };
</script>'''
driver = '''<script>
(function(){
  const q = new URLSearchParams(location.search);
  const cv = document.getElementById('stage');
  const results = [];
  function hash(str){ let h=5381; for(let i=0;i<str.length;i+=97){ h=((h<<5)+h+str.charCodeAt(i))|0; } return (h>>>0).toString(16); }
  function proj(p){ const v = p.clone().project(camera); return [(v.x*0.5+0.5).toFixed(3), (-v.y*0.5+0.5).toFixed(3)].join(','); }
  try {
    const times = [0, 0.6, 2.7, 3.4, 4, 8, 13, 15.2, 17.5, 19.8, 22, 26, 31, 33.6, 35.3, 36.2, 36.6, 38, 40];
    let maxMs = 0;
    for (const t of times) { const s0 = performance.now(); renderAt(t); maxMs = Math.max(maxMs, performance.now() - s0); }
    renderAt(22); const h1 = hash(cv.toDataURL());
    renderAt(5); renderAt(22); const h2 = hash(cv.toDataURL());
    renderAt(36.6); const h3 = hash(cv.toDataURL());
    renderAt(0); renderAt(36.6); const h4 = hash(cv.toDataURL());
    results.push('determinism: ' + (h1===h2 && h3===h4 ? 'PASS' : 'FAIL'));
    results.push('maxRenderMs: ' + maxMs.toFixed(1));
    const t = parseFloat(q.get('t') || '17.5');
    renderAt(t);
    results.push('t=' + t + ' R@' + proj(poseR.pos.clone().add(new THREE.Vector3(0,0.5,0))) + ' B@' + proj(poseB.pos.clone().add(new THREE.Vector3(0,0.5,0))));
    if (t >= 15 && t < 20) {
      results.push('nose@' + proj(new THREE.Vector3(2.8,0.35,0).applyMatrix4(carB.root.matrixWorld)) + ' wingF@' + proj(new THREE.Vector3(2.62,0.1,0.9).applyMatrix4(carB.root.matrixWorld)));
    }
    // gantry pod states
    if (q.get('pods') === '1') {
      for (const tt of [0.4, 0.6, 2.6, 2.99, 3.01, 36.49, 36.55, 36.6]) {
        renderAt(tt);
        results.push('pods t=' + tt + ': ' + podMats.map(m=>m.emissiveIntensity.toFixed(1)).join(',') + ' emissive=' + podMats[0].emissive.getHexString());
      }
    }
    // particle visibility check
    if (q.get('parts') === '1') {
      for (const tt of [3.5, 8, 20.5, 27, 35]) {
        renderAt(tt);
        const cnt = (sys) => { let n=0; for(let i=0;i<sys.n;i++) if(sys.alp[i]>0.01) n++; return n; };
        results.push('parts t=' + tt + ' sprayR=' + cnt(sprayR) + ' smokeR=' + cnt(smokeR) + ' puff=' + cnt(puffR) + ' sparkR=' + cnt(sparkR) + ' sparkB=' + cnt(sparkB));
      }
    }
    if (q.get('drs') === '1') {
      for (const tt of [33.4, 33.56, 34, 36.45, 36.65]) {
        renderAt(tt);
        results.push('drs t=' + tt + ' angle=' + carB.flapPivot.rotation.z.toFixed(3));
      }
    }
  } catch(e) { window.__errs.push('DRIVER: ' + (e.stack || e.message)); }
  document.getElementById('countdown').style.display = 'none';
  const dd = document.createElement('div');
  dd.id = '__report';
  dd.style.cssText = 'position:fixed;top:8px;left:8px;z-index:999;color:#0f0;font:13px monospace;background:rgba(0,0,0,0.75);padding:8px;white-space:pre;';
  dd.textContent = results.join(String.fromCharCode(10)) + String.fromCharCode(10) + 'ERRORS(' + window.__errs.length + '): ' + window.__errs.slice(0,6).join(' | ');
  document.body.appendChild(dd);
})();
</script>'''
